 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:HOA 217", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "2fb832ba-b84e-5336-b9c5-e289ceed3b73", "stem": "The six numbers 9,35,2,18,7,x have sum 76. Using the medians of the lower and upper halves as Q1 and Q3, what is the interquartile range?", "choices": [{"key": "A", "text": "11"}, {"key": "B", "text": "13"}, {"key": "C", "text": "33"}, {"key": "D", "text": "21"}], "type": "mcq", "correct": "B", "explanation": "The known values sum to 71, so x=5. In order the data are 2,5,7,9,18,35. Q1=5 and Q3=18, so the IQR is 18−5=13.", "topic": "Statistics, Probability & Data Analysis", "note": "Specified the quartile convention to avoid method-dependent results.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 129, "extra_sources": [], "parts": [{"label": "Q10", "question_id": "a917e21e-fcbc-5ded-aff6-c0b019197c99", "stem": "Solve the system 4x−3<2x+7 and 3x−5≥x+1.", "choices": [{"key": "A", "text": "[3,5)"}, {"key": "B", "text": "(3,5]"}, {"key": "C", "text": "(3,5)"}, {"key": "D", "text": "[3,5]"}], "type": "mcq", "correct": "A", "explanation": "The first inequality gives x<5; the second gives x≥3. Their intersection is [3,5).", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:HOA 218", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "f046c71d-ff2c-5ea3-b58a-51177e12ffdd", "stem": "C=(−4,−5) is the midpoint of segment AF, and A=(3,2). What is F?", "choices": [{"key": "A", "text": "(0,11)"}, {"key": "B", "text": "(−12,−11)"}, {"key": "C", "text": "(−11,−12)"}, {"key": "D", "text": "(0,12)"}], "type": "mcq", "correct": "C", "explanation": "Use F=2C−A. Its coordinates are 2(−4)−3=−11 and 2(−5)−2=−12.", "topic": "Coordinate Geometry & Circles", "note": "The preceding parallelogram question has a missing figure and unknown parameter a; it remains excluded.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 130, "extra_sources": []}, {"id": "clean:HOA 219", "old_status": "ocr_screened_not_verified", "status": "duplicate", "note": "Visually confirmed the repeated three questions. The verified solutions are x=7/3, least x=−15, and a=11. Reused HOA 191 and its two separately published parts.", "correct": ["B", "B", "11"], "question_id": "d30b25d5-c436-5e7a-a426-9d512580bbcd", "duplicate_of": "clean:HOA 191"}, {"id": "clean:HOA 221", "old_status": "ocr_screened_not_verified", "status": "needs_source_reconstruction", "note": "The radical bar is absent in this crop. Read as √x+2=2 the answer is x=0 (C), while the matching earlier question HOA 194 clearly shows √(x+2)=2 and gives x=2 (A). Because this copy’s scope cannot be confirmed, do not merge conflicting interpretations or approve a letter; retain the clear HOA 194 version.", "correct": null}, {"id": "clean:HOA 222", "old_status": "ocr_screened_not_verified", "status": "duplicate", "note": "Exact repeated segment relation AC=6, BD=3AC=6x+9. Verified x=1.5; reused the corrected diagonal terminology in HOA 195.", "correct": "A", "question_id": "29b98515-a63e-50cb-b70a-638b1de4ad32", "duplicate_of": "clean:HOA 195"}, {"id": "clean:HOA 223", "old_status": "ocr_screened_not_verified", "status": "duplicate", "note": "Exact repeated functions and evaluation. f(−1)=−2, g(−2)=15, product −30. Reused HOA 197.", "correct": "A", "question_id": "aca80e69-8371-553e-a106-156f558ec5cb", "duplicate_of": "clean:HOA 197"}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
