BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:HOA 233", "old_status": "ocr_screened_not_verified", "status": "needs_source_reconstruction", "note": "The source asks for f(−2) but gives f′(x)=(2x−5)(x+1). An arbitrary integration constant prevents determining f(−2). If the prime is a typo, f(−2)=9, but this cannot be silently assumed. Retain pending a corrected source.", "correct": null}, {"id": "clean:HOA 237", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "eb209219-0811-593a-acaa-aefc6c923f64", "stem": "What is the greater solution of 2(x+5)²−1=7?", "choices": [{"key": "A", "text": "−3"}, {"key": "B", "text": "−1"}, {"key": "C", "text": "3"}, {"key": "D", "text": "7"}], "type": "mcq", "correct": "A", "explanation": "Add 1 and divide by 2: (x+5)²=4. Thus x+5=±2, giving x=−3 or −7. The greater root is −3.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 142, "extra_sources": []}, {"id": "clean:HOA 239", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "8aeb63f8-7f20-5480-9487-c6ad9e86f6b0", "stem": "Solve 3.8y+(4/7)x+2=0 for y.", "choices": [{"key": "A", "text": "y=−10/19"}, {"key": "B", "text": "y=−(20/133)x−10/19"}, {"key": "C", "text": "y=−(4/7)x−2"}, {"key": "D", "text": "y=−(76/35)x−38/5"}], "type": "mcq", "correct": "B", "explanation": "Since 3.8=19/5, isolate (19/5)y=−(4/7)x−2 and multiply by 5/19. This gives y=−(20/133)x−10/19.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 143, "extra_sources": []}, {"id": "clean:PSD 012", "old_status": "ocr_screened_not_verified", "status": "worked_missing_choice", "note": "Verified constraints are 10a+25b≤250 and 45a+120b≥900, for nonnegative integer jar counts a,b. The correct combination is absent from surviving choices A–C and D is missing, including on the next page. Retain until the original D is recovered.", "correct": "10a+25b≤250; 45a+120b≥900"}, {"id": "clean:PSD 019", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "18c5d7b2-d943-5c06-9742-29ad381e35a0", "stem": "In a random sample of 250 out of 4900 lawyers, 80 report that murder cases are their most frequent case type. Use the sample proportion to estimate the corresponding number among all 4900 lawyers.", "choices": [], "type": "grid_in", "correct": "1568", "explanation": "The sample proportion is 80/250=0.32. Multiplying by 4900 gives an estimate of 1568 lawyers.", "topic": "Statistics, Probability & Data Analysis", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 159, "extra_sources": []}, {"id": "clean:PSD 020", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "7f707759-66bd-523c-a34c-9393c843a7a2", "stem": "Let p(x)=x²−7x+5 and q(x)=−3x³−7x²+2x−5. What is p(x)−q(x)?", "choices": [{"key": "A", "text": "4x³−9x+10"}, {"key": "B", "text": "−3x³−6x²−5x"}, {"key": "C", "text": "−3x³−8x²+9x−10"}, {"key": "D", "text": "3x³+8x²−9x+10"}], "type": "mcq", "correct": "D", "explanation": "Distribute the subtraction: x²−7x+5+3x³+7x²−2x+5=3x³+8x²−9x+10.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "The separate current-frequency graph is retained unpublished because the written 60–80 Hz domain conflicts with the full displayed curve and candidate intersections.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 160, "extra_sources": []}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
