oices": [{"key": "A", "text": "5−0.5c"}, {"key": "B", "text": "15−c"}, {"key": "C", "text": "30−0.5c"}, {"key": "D", "text": "15−0.5c"}], "type": "mcq", "correct": "D", "explanation": "The mean equation gives a+b+c=30, so a+b=30−c. Divide by 2: (a+b)/2=15−0.5c.", "topic": "Statistics, Probability & Data Analysis", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 162, "extra_sources": []}, {"id": "clean:PSD 024", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "72c1fcf6-aea8-5c2a-8efe-cdf7c2a2879e", "stem": "A population model starts at 120 people and doubles every 3 months. Which equation determines the number m of months until it reaches 1500?", "choices": [{"key": "A", "text": "120·2^(m/3)=1500"}, {"key": "B", "text": "120·2^(3m)=1500"}, {"key": "C", "text": "2·120^(m/3)=1500"}, {"key": "D", "text": "1500·2^(m/3)=120"}], "type": "mcq", "correct": "A", "explanation": "There are m/3 doubling periods in m months. The modeled population is 120·2^(m/3); set this equal to 1500.", "topic": "Functions, Transformations & Graphs", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 163, "extra_sources": []}, {"id": "clean:PSD 026", "old_status": "ocr_screened_not_verified", "status": "needs_source_reconstruction", "note": "The source gives a 15% overall test-error rate, but does not specify how many errors are false positives versus false negatives, or precisely which denominator the 15% uses. An overall error rate alone does not determine the number actually healthy in the age group. The original answer labels also repeat A. Retain pending complete test/outcome information.", "correct": null}, {"id": "clean:PSD 030", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "aa41f870-bb89-536f-b97b-46a08b4ef542", "stem": "The measured gas mass is M=1.61t+3.95 grams, where t is seconds. By how many grams does M increase over any 10-second interval?", "choices": [], "type": "grid_in", "correct": "16.1", "explanation": "M(t+10)−M(t)=1.61·10=16.1 grams. The constant 3.95 cancels.", "topic": "Functions, Transformations & Graphs", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 169, "extra_sources": [], "parts": [{"label": "Q32", "question_id": "272601d0-9dc2-56da-b0a1-cef1347dbc3f", "stem": "A game starts a player with 10 coins, adds 3 per correct answer, and subtracts 1 per wrong answer. Each final coin is worth $3. Jad makes 4 errors and receives $153. How many correct answers did he give?", "choices": [], "type": "grid_in", "correct": "15", "explanation": "The final coin total is 153/3=51. With c correct answers, 10+3c−4=51, so 3c=45 and c=15.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}]$payload$::jsonb) LOOP
