 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:PSD 130", "old_status": "ocr_screened_not_verified", "status": "needs_source_reconstruction", "note": "The first question’s initial score is missing. The email-chart question has unreadable axis labels and an incomplete requested rate/interval; its fractional choices also conflict with a whole-number instruction. Neither has a verifiable unique answer from this source.", "correct": null}, {"id": "clean:PSD 131", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "cecce1bc-5686-58fa-9803-3f7b40b1c266", "stem": "Sales increase from 40000 units in January to 60000 in February. What is the percentage increase?", "choices": [{"key": "A", "text": "25%"}, {"key": "B", "text": "33%"}, {"key": "C", "text": "50%"}, {"key": "D", "text": "67%"}], "type": "mcq", "correct": "C", "explanation": "The increase is 20000 units. Relative to 40000, the increase is 20000/40000·100=50%.", "topic": "Statistics, Probability & Data Analysis", "note": "Isolated complete Q14. Q11/Q12 have no readable fitted line/model. Q13 does not explicitly establish that 700 is the mode; its median cannot be uniquely inferred. Those fragments remain excluded.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 248, "extra_sources": []}, {"id": "clean:PSD 132", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "1b9f821a-f99f-5ea7-8f1d-97f2c4ce6217", "stem": "A $6000 investment compounded annually grows to approximately $8950.95 after 8 years. Which annual interest rate is consistent with this amount?", "choices": [{"key": "A", "text": "3%"}, {"key": "B", "text": "1%"}, {"key": "C", "text": "5%"}, {"key": "D", "text": "7%"}], "type": "mcq", "correct": "C", "explanation": "The model is 6000(1+r)⁸=8950.95. At r=0.05, the amount is 6000·1.05⁸≈8950.95. Thus the rate is 5%.", "topic": "Functions, Transformations & Graphs", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 249, "extra_sources": []}, {"id": "clean:PSD 133", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "3ee969b5-2e4c-575e-955f-4083ccb4a1f4", "stem": "A total of $149 is split among a father, son, and daughter in the ratio 3:3:2. What is the total share received by the children, before rounding?", "choices": [{"key": "A", "text": "$55.875"}, {"key": "B", "text": "$145.7"}, {"key": "C", "text": "$93.125"}, {"key": "D", "text": "$111.6"}], "type": "mcq", "correct": "C", "explanation": "The children receive 3+2=5 of the 8 ratio parts. Their combined share is 149·5/8=93.125 dollars.", "topic": "Statistics, Probability & Data Analysis", "note": "Clarified the original “how much hasn’t the father got” as the complementary children’s share.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 250, "extra_sources": [], "parts": [{"label": "Q24", "question_id": "659ff5d0-36b5-58d6-89f1-367d313fd08f", "stem": "A math book costs $75. An English book costs 40% less. One math book, one English book, and 3 copybooks cost $153. What is the combined cost of the 3 copybooks?", "choices": [{"key": "A", "text": "$11"}, {"key": "B", "text": "$33"}, {"key": "C", "text": "$4"}, {"key": "D", "text": "$66"}], "type": "mcq", "correct": "B", "explanation": "The English book costs 75·0.60=45. The two textbooks cost 120, leaving 153−120=33 for the three copybooks.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:PSD 134", "old_status": "ocr_screened_not_verified", "status": "worked_missing_choice", "note": "The displayed temperature data are 17,22,21,18,22,28,21,26,38,31,26,19. A correct tens-stem plot is 1|7 8 9; 2|1 1 2 2 6 6 8; 3|1 8. The answer plots are incomplete/cut and B/D are absent. Record the verified plot but do not infer an answer letter.", "correct": "1|789;2|1122668;3|18"}, {"id": "clean:PSD 135", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "6e34a7b4-86a4-5a15-a232-f42c118b965e", "stem": "There are 12 cards: four labeled 1, four labeled 2, and four labeled 3. Two cards are drawn uniformly without replacement. What is the probability they have the same label?", "choices": [], "type": "grid_in", "correct": ["3/11", "0.272727272727273"], "explanation": "Whatever the first card’s label, 3 of the remaining 11 cards match it. Therefore the probability is 3/11.", "topic": "Statistics, Probability & Data Analysis", "note": "Counted the displayed string 111122223333. Used numeric response because D is cut off and 0.3 is not the exact probability.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 251, "extra_sources": []}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260928') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
