 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:PSD 208", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "2921ffed-5377-513a-90d2-42ecfaa7017c", "stem": "The numbers 8,10,12,17,19,20,t,25 have mean 17 and median n. What is n+t?", "choices": [{"key": "A", "text": "18"}, {"key": "B", "text": "25"}, {"key": "C", "text": "17"}, {"key": "D", "text": "43"}], "type": "mcq", "correct": "D", "explanation": "Their total is 8·17=136; the known sum is 111, so t=25. The middle two sorted values are 17 and 19, giving n=18. Thus n+t=43.", "topic": "Statistics, Probability & Data Analysis", "note": "The preceding subject-median question has no accompanying subject data and remains excluded.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 297, "extra_sources": []}, {"id": "clean:PSD 209", "old_status": "ocr_screened_not_verified", "status": "duplicate", "note": "Exact repeated ball-count question. Non-red probability is (2+7)/(3+2+7)=9/12; reused PSD 176.", "correct": "A", "question_id": "880ed819-a217-5918-91c8-c25fa7798c7a", "duplicate_of": "clean:PSD 176"}, {"id": "clean:PSD 210", "old_status": "ocr_screened_not_verified", "status": "duplicate", "note": "Exact repeated ratio problem: girls=4550·2/7=1300; girls without glasses=1300−105=1195. Reused the existing complete PSD 177.", "correct": "A", "question_id": "40063caa-b9e2-5f43-b79e-5d413bf7932f", "duplicate_of": "clean:PSD 177", "before": {"stem": "PSD 177 — Answer the original question below.", "choices": [{"key": "A", "text": "Option A in the original question"}, {"key": "B", "text": "Option B in the original question"}, {"key": "C", "text": "Option C in the original question"}, {"key": "D", "text": "Option D in the original question"}], "correct": "A", "explanation": "Girls=4550*2/7=1300. Girls without glasses=1300-105=1195."}}, {"id": "clean:PSD 211", "old_status": "ocr_screened_not_verified", "status": "duplicate", "note": "Exact repeated typing-rate question: Ahmed 125 words/min, Malak 250, so 3.5 minutes yields 875 words. Reused PSD 178. The opening inverse-function choices also complete PAM 083.", "correct": "B", "question_id": "45c568bf-a2b7-5041-8911-62c986666461", "duplicate_of": "clean:PSD 178", "before": {"stem": "PSD 178 — Answer the original question below.", "choices": [{"key": "A", "text": "Option A in the original question"}, {"key": "B", "text": "Option B in the original question"}, {"key": "C", "text": "Option C in the original question"}, {"key": "D", "text": "Option D in the original question"}], "correct": "B", "explanation": "Ahmed types 125 words/minute; Malak types 250. Over 3.5 minutes she types 875 words."}}, {"id": "clean:PSD 212", "old_status": "ocr_screened_not_verified", "status": "duplicate", "note": "Exact repeated three-digit counting question; 4 even nonzero hundreds digits ×10 tens ×5 odd units=200. Reused PSD 179.", "correct": "B", "question_id": "33348087-c932-5572-80d5-ca6f26a532fc", "duplicate_of": "clean:PSD 179"}, {"id": "clean:PSD 213", "old_status": "ocr_screened_not_verified", "status": "duplicate", "note": "Repeated mean-minus-median question (26/7), compound-interest question ($559), and pair-substitution question (2xy=1). Reused PSD 180, PSD 181, and HOA 207 respectively.", "correct": ["B", "A", "C"], "question_id": "1b1c2b51-a019-57a8-8ac0-5fdef67a9551", "duplicate_of": "clean:PSD 180"}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260928') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
